CREATE TABLE IF NOT EXISTS calls ( id TEXT PRIMARY KEY, call_type TEXT NOT NULL DEFAULT '', visit_date TEXT NOT NULL DEFAULT '', updated TEXT NOT NULL DEFAULT '', deleted TEXT NOT NULL DEFAULT '', data TEXT NOT NULL );
CREATE INDEX IF NOT EXISTS calls_updated ON calls(updated);
CREATE INDEX IF NOT EXISTS calls_deleted ON calls(deleted);
CREATE INDEX IF NOT EXISTS calls_type_date ON calls(call_type, visit_date);
CREATE TABLE IF NOT EXISTS members ( emp TEXT NOT NULL, name TEXT NOT NULL, added TEXT NOT NULL DEFAULT '', "by" TEXT NOT NULL DEFAULT '', deleted TEXT NOT NULL DEFAULT '' );
CREATE INDEX IF NOT EXISTS members_emp ON members(emp);
CREATE TABLE IF NOT EXISTS quotereq ( id TEXT PRIMARY KEY, at TEXT NOT NULL DEFAULT '', org TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', date TEXT NOT NULL DEFAULT '', pax TEXT NOT NULL DEFAULT '', memo TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT '접수', "by" TEXT NOT NULL DEFAULT '', doneAt TEXT NOT NULL DEFAULT '', deleted TEXT NOT NULL DEFAULT '' );
CREATE TABLE IF NOT EXISTS files ( id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', mime TEXT NOT NULL DEFAULT '', size INTEGER NOT NULL DEFAULT 0, at TEXT NOT NULL DEFAULT '', "by" TEXT NOT NULL DEFAULT '' );
CREATE TABLE IF NOT EXISTS file_chunks ( id TEXT NOT NULL, n INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY (id, n) );
CREATE TABLE IF NOT EXISTS locks ( id TEXT PRIMARY KEY, sid TEXT NOT NULL, "by" TEXT NOT NULL DEFAULT '', at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS kv ( k TEXT PRIMARY KEY, v TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS quote_history ( id TEXT PRIMARY KEY, at TEXT NOT NULL DEFAULT '', data TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS clergy ( id TEXT PRIMARY KEY, visit_date TEXT NOT NULL DEFAULT '', org TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', pos TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '', turn TEXT NOT NULL DEFAULT '', who TEXT NOT NULL DEFAULT '', added TEXT NOT NULL DEFAULT '', "by" TEXT NOT NULL DEFAULT '', updated TEXT NOT NULL DEFAULT '', deleted TEXT NOT NULL DEFAULT '' );
CREATE INDEX IF NOT EXISTS clergy_who ON clergy(who);
CREATE INDEX IF NOT EXISTS clergy_date ON clergy(visit_date);
CREATE TABLE IF NOT EXISTS press ( id TEXT PRIMARY KEY, list TEXT NOT NULL DEFAULT '', cat TEXT NOT NULL DEFAULT '', media TEXT NOT NULL DEFAULT '', name TEXT NOT NULL DEFAULT '', pos TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', memo TEXT NOT NULL DEFAULT '', ord REAL NOT NULL DEFAULT 0, updated TEXT NOT NULL DEFAULT '', "by" TEXT NOT NULL DEFAULT '', deleted TEXT NOT NULL DEFAULT '' );
CREATE INDEX IF NOT EXISTS press_list ON press(list);

